// 32 reviewed source-based cases. Scenarios and judgements are original adaptations.
export const CASES=[{"id":"dujiangyan","name":"都江堰分水工程","date":"公元前3世纪","fact":"都江堰以分水、排沙等工程持续调控岷江水流。","dilemma":"上游来水多沙，灌溉、行洪与长期维护必须兼顾。","options":["设计分流排沙并组织持续维护","把全部来水集中进单一灌渠","先扩大耕地，等淤积后再治理"],"explanation":"在题设的多沙河流中，排沙与维护是持续供水的必要条件。","url":"https://whc.unesco.org/en/list/1001"},{"id":"tu","name":"青蒿素研究中的提取调整","date":"1971年前后","fact":"屠呦呦团队从古籍获得启发，调整提取方法并开展实验研究。","dilemma":"传统线索与高温提取效果不一致，需要改变研究路径。","options":["比较低温方法，保留实验记录并验证","只扩大原有高温方法的实验次数","直接把古籍记载当成疗效证明"],"explanation":"线索提供假设，实验才能检验；游戏不提供现实用药建议。","url":"https://www.nobelprize.org/prizes/medicine/2015/tu/biographical/"},{"id":"fire","name":"伦敦大火后的建设反思","date":"1666年","fact":"伦敦大火造成严重破坏，留下大量灾情记录与重建问题。","dilemma":"连片建筑与火灾损失迫使城市重新考虑恢复速度和防火。","options":["核实灾损，兼顾避险与分阶段重建","先恢复原有密集布局以最快复业","等待所有规划统一后才提供临时安置"],"explanation":"本题优先保障安置并减少重复风险，不声称所有重建争议只有一个历史答案。","url":"https://www.nationalarchives.gov.uk/education/resources/significant-events/great-fire-of-london-1666/"},{"id":"magna","name":"大宪章中的权力约束","date":"1215年","fact":"英王约翰与贵族在冲突中达成大宪章安排，后续仍有反复与修订。","dilemma":"强势统治与既有权利冲突，协商结果需要留下可核对的承诺。","options":["把协商承诺写入可检查的文本","只保留口头保证以便灵活应变","先扩大冲突再考虑任何约定"],"explanation":"1215年的安排主要回应当时的权力关系，不能等同现代普遍权利制度。","url":"https://www.nationalarchives.gov.uk/explore-the-collection/explore-by-time-period/medieval/magna-carta/"},{"id":"penicillin","name":"青霉素从发现走向应用","date":"1928—1945年","fact":"弗莱明的发现与钱恩、弗洛里的研究共同推动青霉素的治疗应用。","dilemma":"实验室现象尚不能直接变成稳定可用的产品。","options":["组织纯化、验证与跨专业协作","只发表最初现象便结束后续工作","把少量粗提物立刻推广给所有人"],"explanation":"发现、验证、生产是不同环节；成果需要团队接续。","url":"https://www.nobelprize.org/prizes/medicine/1945/summary/"},{"id":"challenger","name":"挑战者号的发射决策教训","date":"1986年","fact":"罗杰斯委员会指出挑战者号发射决策、信息沟通与安全管理存在问题。","dilemma":"低温与密封风险尚有争议，进度压力正在上升。","options":["暂停并让风险证据进入正式决策","按原窗口发射，后续再补充论证","把争议仅留在承包商内部"],"explanation":"在高后果风险下，未解决的安全疑点必须进入有权决策的层级。","url":"https://sma.nasa.gov/SignificantIncidents/assets/rogers_commission_report.pdf"},{"id":"columbia","name":"哥伦比亚号事故调查","date":"2003年","fact":"发射时脱落的泡沫撞击机翼，造成的损伤与再入灾难相关。","dilemma":"过去曾出现的异常再次发生，不能仅凭过去侥幸无事判定安全。","options":["独立核验损伤并升级报告","按以往经验归为正常现象","只关注原定任务成果"],"explanation":"调查强调物理损伤和组织决策，题目不声称一句正确汇报就必能改写事故。","url":"https://www.nasa.gov/remembering-columbia-sts-107/"},{"id":"web","name":"万维网软件开放","date":"1993年","fact":"CERN将万维网软件置于公共领域，推动了开放网络的发展。","dilemma":"新工具需要跨机构采用，封闭许可与开放传播形成取舍。","options":["明确开放许可和技术规范","每个机构采用不兼容的私有格式","只分享展示结果而不提供工具"],"explanation":"此题目标是促进互操作传播，开放策略与目标匹配，并非所有项目都应无条件开放。","url":"https://home.cern/science/computing/the-birth-of-the-web"},{"id":"helicobacter","name":"幽门螺杆菌研究","date":"1980年代","fact":"马歇尔和沃伦发现幽门螺杆菌与胃炎、消化性溃疡相关，挑战了既有认识。","dilemma":"反常观察与流行解释相冲突，需要决定是否继续检验。","options":["保留样本并用可复核研究检验","只挑选符合旧解释的样本","把个人直觉直接当作临床标准"],"explanation":"历史人物曾采取的高风险行为不应照搬；游戏奖励的是证据核验而非自我试药。","url":"https://www.nobelprize.org/prizes/medicine/2005/press-release/"},{"id":"zhangqian","name":"张骞出使与跨域信息","date":"公元前2世纪","fact":"张骞的外交出使增进了汉朝对中亚地区的了解。","dilemma":"陌生地区的地理、风俗和政治情况尚不清楚。","options":["记录可核实见闻并尊重当地差异","把沿途传闻都写成已证实事实","只记录符合出发前设想的信息"],"explanation":"外交目的与后来商路交流不能混为同一个单一目标。","url":"https://whc.unesco.org/en/list/1442"},{"id":"xuanzang","name":"玄奘求学与文献传译","date":"7世纪","fact":"玄奘赴印度求学并带回文献，推动跨语言知识交流。","dilemma":"不同语言文本之间存在术语差异与理解障碍。","options":["比较文本并组织精通语言者校核","只按字面机械替换全部术语","用自己熟悉的故事填补缺失原文"],"explanation":"本题关注知识传译，区分历史行旅与文学神魔故事。","url":"https://idp.bl.uk/discover/learning/buddhism-on-the-silk-roads/articles/transmission-of-buddhism/buddhist-travellers-and-pilgrims/"},{"id":"bisheng","name":"毕昇活字的工艺选择","date":"11世纪","fact":"毕昇以单字字模发展活字印刷，印刷工艺存在成本与适用场景差异。","dilemma":"反复改版和小批量任务需要灵活排版，但设备投入有限。","options":["比较批量和改版成本后试用活字","不看任务差异就替换全部旧工艺","只保留旧工艺而不做任何试验"],"explanation":"技术适用性依成本和文字环境而异，不能把后来的普及程度当成当时必然结果。","url":"https://afe.easia.columbia.edu/songdynasty-module/tech-printing.html"},{"id":"montreal","name":"蒙特利尔议定书的合作机制","date":"1987年","fact":"各国通过议定书逐步淘汰消耗臭氧层的物质。","dilemma":"污染跨越边界，替代技术与产业转型又需要时间。","options":["约定分阶段目标并跟踪履约","只由单个地区行动且不交换数据","一次宣布目标但不安排后续核查"],"explanation":"合作机制、实施节奏与持续监测共同支撑长期环境治理。","url":"https://ozone.unep.org/treaties/montreal-protocol"},{"id":"seedvault","name":"斯瓦尔巴种子库的备份","date":"2008年","fact":"全球种子库为不同地区的作物种质资源提供安全备份。","dilemma":"地方保存设施可能因灾害或冲突受损，样本需要冗余。","options":["保留地方库并建立异地备份","把全部原样本转移后关闭地方库","只保存当前高产的少数品种"],"explanation":"备份是风险分散，不能取代日常维护与生物多样性。","url":"https://www.croptrust.org/what-we-do/programs/svalbard-global-seed-vault/"},{"id":"marshall","name":"马歇尔计划的重建协调","date":"1948年","fact":"欧洲复兴计划通过经济援助支持战后欧洲重建。","dilemma":"恢复生产需要各方协调，也涉及援助条件与本地需求。","options":["明确目标并让受援方参与安排","只追求援助总额而不追踪用途","不顾当地承载力一次投放所有物资"],"explanation":"这是特定战后背景下的政策案例，不将其所有后果简化为一致评价。","url":"https://www.archives.gov/milestone-documents/marshall-plan"},{"id":"berlin","name":"柏林空运的运输组织","date":"1948—1949年","fact":"陆路受阻后，美英等通过持续空运向西柏林供应物资。","dilemma":"补给中断而直接对抗可能升级风险，运输能力又有限。","options":["核算运力，优先必需品并协调航班","先运高价值展示品以证明行动规模","各机组自行安排时刻与降落"],"explanation":"题设关注后勤调度与风险控制，不把空运抽象成无成本方案。","url":"https://www.trumanlibrary.gov/library/online-collections/berlin-airlift"},{"id":"cuba","name":"古巴导弹危机中的升级控制","date":"1962年","fact":"美国采取海上隔离并展开交涉，危机最终通过谈判缓解。","dilemma":"对方行动引发严重威胁，立即攻击和谈判都存在风险。","options":["保留沟通渠道并采取可控措施","不给对方核实与回应时间即全面攻击","只依公开强硬表态拒绝秘密沟通"],"explanation":"本题的优先目标是降低失控风险；各方利益与历史争议不因游戏判分而消失。","url":"https://www.archives.gov/news/topics/cuban-missile-crisis"},{"id":"dday","name":"诺曼底行动的天气窗口","date":"1944年","fact":"盟军因天气推迟原定行动，并据预报选择6月6日的窗口。","dilemma":"计划已准备完毕，但海况与能见度影响行动安全。","options":["综合预报与任务条件重新判断窗口","仅因计划公布便拒绝调整","等到完全没有天气不确定性才行动"],"explanation":"决策是在不确定中比较风险，不能要求预报保证零风险。","url":"https://www.metoffice.gov.uk/research/library-and-archive/archive-hidden-treasures/d-day"},{"id":"smog","name":"伦敦烟雾与空气治理","date":"1952年及以后","fact":"严重烟雾暴露燃煤污染风险，之后英国推进清洁空气立法。","dilemma":"供暖需求真实存在，而长期污染造成健康损失。","options":["安排清洁替代并持续监测排放","只把污染归因于天气而不减排","立刻切断全部供暖但不提供替代"],"explanation":"环境治理需兼顾减排与基本生活，不能把成本留给承受能力最低的人。","url":"https://weather.metoffice.gov.uk/learn-about/weather/case-studies/great-smog"},{"id":"dustbowl","name":"沙尘暴与土壤保护","date":"1930年代","fact":"美国尘暴与干旱、土地管理问题交织，推动土壤保护工作。","dilemma":"短期扩大耕作可增收，却可能进一步暴露干燥表土。","options":["结合保护耕作与农户过渡支持","为补偿损失继续扩大裸地开垦","只宣传生态目标而不给实践支持"],"explanation":"灾害成因不止一个，政策要把生态修复和生计同时纳入。","url":"https://www.nrcs.usda.gov/about/history/brief-history-nrcs"},{"id":"yellowstone","name":"黄石国家公园的保护选择","date":"1872年","fact":"黄石被设立为国家公园，确立了特定区域保护与公共管理安排。","dilemma":"自然景观面临开发压力，保护还牵涉既有居民与公共使用。","options":["设保护规则并审视不同群体权益","把所有景观立即分割为独占项目","只设立名称却不安排管理责任"],"explanation":"早期保护史包含对原住民的排斥；游戏不把历史保护制度理想化。","url":"https://www.nps.gov/yell/learn/historyculture/yellowstoneestablishment.htm"},{"id":"shackleton","name":"坚忍号之后的救援目标","date":"1915—1916年","fact":"坚忍号受困后，沙克尔顿及团队转向生存与求援，留岛队员最终获救。","dilemma":"原定探索目标已经失去条件，队员与物资仍需统筹。","options":["转为保全人员并组织可行求援","为保持原目标而继续消耗补给","让各人独自寻找生路以减少负担"],"explanation":"更换目标不是自动成功，航海技能、协作与外部援助同样关键。","url":"https://www.rmg.co.uk/stories/maritime-history/sir-ernest-shackleton"},{"id":"harrison","name":"航海钟与经度难题","date":"18世纪","fact":"哈里森研制计时装置，以精确计时帮助海上经度测定。","dilemma":"海上导航需要可靠时标，新装置必须经真实航行验证。","options":["在航海条件下检验误差和可靠性","只看静置时精度便宣布解决问题","先追求外观体面再考虑稳定性"],"explanation":"真实环境验证比单一理想指标更能反映系统是否可用。","url":"https://www.rmg.co.uk/collections/objects/rmgc-object-79142"},{"id":"hubble","name":"哈勃望远镜的在轨修复","date":"1993年","fact":"航天员安装校正光学装置等设备，改善了哈勃的成像。","dilemma":"昂贵设备已经投入使用，已知缺陷需要修复方案而非掩饰。","options":["查明缺陷并验证可执行修复方案","只挑选较好的图像否认缺陷","未比较修复成本就废弃整个系统"],"explanation":"维护能力与先前设计的接口为修复创造条件，不能忽略工程准备。","url":"https://science.nasa.gov/mission/hubble/observatory/missions-to-hubble/"},{"id":"marsunits","name":"火星气候轨道器的单位错误","date":"1999年","fact":"轨道器任务失败与英制和公制数据处理不一致有关。","dilemma":"不同团队接口中的同名数值采用不同单位。","options":["统一单位契约并做端到端校验","仅确认各子系统各自能运行","把换算责任留给下游临场判断"],"explanation":"局部合格不等于系统正确，接口必须有明确可测试的约定。","url":"https://science.nasa.gov/mission/mars-climate-orbiter/"},{"id":"quake","name":"旧金山地震的风险认识","date":"1906年","fact":"旧金山附近大地震造成广泛破坏，为后续断层与震害研究留下资料。","dilemma":"破坏范围很大，恢复决策需要可靠记录而不是单点印象。","options":["记录各区损害并据风险安排恢复","只修复最显眼的中心建筑","等到能精确预测下一次地震才准备"],"explanation":"游戏强调基于损害与风险准备，不声称地震已能精确预测。","url":"https://earthquake.usgs.gov/education/shakingsimulations/1906/"},{"id":"rosetta","name":"罗塞塔石碑与跨文字比对","date":"19世纪","fact":"同一铭文的不同文字版本为古埃及文字释读提供关键线索。","dilemma":"陌生文字不能靠单一猜测译出，需要可比较样本。","options":["比较不同文字的对应并交叉验证","只凭图形相似为每个字赋义","把无法解释之处全部删除"],"explanation":"释读依赖长期积累与多份材料，不是靠一块石碑瞬间解开全部文字。","url":"https://www.britishmuseum.org/sites/default/files/2022-10/Hieroglyphs_unlocking_ancient_Egypt_large_print_guide_The_British_Museum_2.pdf"},{"id":"apolloair","name":"阿波罗13号的任务重定向","date":"1970年","fact":"氧气罐事故后，团队取消登月并利用登月舱维持返航。","dilemma":"继续原目标将威胁人员生存，剩余资源必须重新配置。","options":["取消原目标并协调生命支持与返航","按原任务清单继续消耗资源","只等待地面给出不需任何代价的方案"],"explanation":"对应历史中的应急改向；题目判断着眼于明确的生存优先目标。","url":"https://www.nasa.gov/missions/apollo/apollo-13-mission-details/"},{"id":"snowwater","name":"宽街水泵的调查与预防","date":"1854年","fact":"斯诺比较霍乱病例与水源线索，推动停止使用可疑水泵。","dilemma":"线索尚需补充，但可疑供水可能带来持续风险。","options":["继续调查同时限制可疑来源并提供替代","等到掌握全部机制才采取任何保护","只按街区名声判断居民是否有风险"],"explanation":"病例下降还受人口离开等因素影响，不能把全部效果归给单次措施。","url":"https://www.cdc.gov/mmwr/preview/mmwrhtml/mm5334a1.htm"},{"id":"poxwatch","name":"消灭天花后的持续监测","date":"1980年","fact":"全球接种、监测和协作使天花得以被宣布消灭。","dilemma":"成功来自多年积累，如何核验最后的传播链成为关键。","options":["持续监测并对异常报告复核","只以一地短期零病例宣布全球完成","把监测预算全部改成庆祝活动"],"explanation":"题目借鉴长期监测机制，不提供现实疫苗接种建议。","url":"https://www.who.int/emergencies/situations/smallpox/"},{"id":"nubiaworks","name":"努比亚古迹的建设与保护","date":"1960年起","fact":"国际行动对受水位上涨威胁的古迹开展记录、抢救和迁移。","dilemma":"大型建设与文化遗产保护发生时间和资源冲突。","options":["比较方案并组织记录与保护协作","把所有旧物都视为可直接丢弃","只讨论保护口号而不安排时间预算"],"explanation":"遗产迁移仍有不可逆代价，不能把抢救解释为完全没有损失。","url":"https://whc.unesco.org/en/activities/172/"},{"id":"nightingale","name":"南丁格尔的统计表达","date":"19世纪","fact":"南丁格尔以统计和图示讨论军队死亡与卫生问题。","dilemma":"决策者难以从大量数字中识别可预防的损失。","options":["整理可核查数据并清楚说明图表局限","只展示最能震撼观众的孤立数字","因数据不完美而完全放弃记录"],"explanation":"图表服务证据，不能用视觉感染力替代数据质量。","url":"https://www.sems.qmul.ac.uk/content/edi/educationresources/files/Diversifying_and_Decolonising_the_Curriculum__SEMS_SMS_V7.pdf"}];
